const items = $input.all();
const raw = items[0].json;
const body = raw.body || raw;
const youtubeUrl = (body.youtubeUrl || '').trim();
const numberOfClips = Math.max(1, Math.min(10, parseInt(body.numberOfClips) || 3));
const aspectRatio = (body.aspectRatio || '9:16').trim();
const applyCaptions = (body.applyCaptions || 'no').toString().toLowerCase().trim();
const ytRegex = /(?:youtube\.com\/(?:watch\?v=|shorts\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
const ytMatch = youtubeUrl.match(ytRegex);
if (!ytMatch) { throw new Error('Invalid YouTube URL. Aspect ratio must be 9:16 or 1:1.'); }
const validRatios = ['9:16', '1:1'];
if (!validRatios.includes(aspectRatio)) { throw new Error('Invalid YouTube URL. Aspect ratio must be 9:16 or 1:1.'); }
if (numberOfClips < 1 || numberOfClips > 10) { throw new Error('Number of clips must be between 1 and 10.'); }
const videoId = ytMatch[1];
const executionId = 'exec-' + Date.now();
return [{ json: { youtubeUrl, videoId, numberOfClips, aspectRatio, applyCaptions: applyCaptions === 'yes', executionId, workflowStartTime: Date.now() } }];

const err = $input.first().json;
const errorMessage = (err.error && err.error.message) ? err.error.message : (err.message || 'Workflow execution failed');
return [{ json: { clipNumber: 0, videoTitle: 'YT Automation', hookTitle: 'Error: ' + errorMessage, igReelLink: '', youtubeShortLink: '', status: 'Aborted', timespent: 'N/A', errorMessage: errorMessage } }];

const rapid = $input.first().json;
const validated = $('Validate + Normalize').first().json;
const { numberOfClips, aspectRatio, applyCaptions, executionId, workflowStartTime, videoId } = validated;

// SocialKit /youtube/download response shape:
// { success: true, data: { title, duration: "3:33", downloadUrl, fileSize, fileSizeMB, format, quality, expiresIn } }
const data = rapid.data || rapid;

const videoUrl = data.downloadUrl || data.url;
if (!videoUrl) {
  throw new Error(
    'Could not extract video URL from SocialKit response. ' +
    'Top-level keys: ' + Object.keys(rapid).join(', ') + '. ' +
    'Raw (first 500 chars): ' + JSON.stringify(rapid).slice(0, 500)
  );
}

const videoTitle = data.title || 'YouTube Video';

// duration comes back as "MM:SS" or "H:MM:SS" string, convert to seconds
let durationSeconds = 300;
if (data.duration) {
  const parts = data.duration.toString().split(':').map(function(p) { return parseInt(p, 10) || 0; });
  if (parts.length === 3) durationSeconds = parts[0] * 3600 + parts[1] * 60 + parts[2];
  else if (parts.length === 2) durationSeconds = parts[0] * 60 + parts[1];
  else if (parts.length === 1) durationSeconds = parts[0];
}

const systemPrompt = 'You are a viral video strategist. Identify the most engaging clip timestamps from YouTube video metadata. Return ONLY a valid JSON array, no markdown, no explanation.';
const userPrompt = 'Video Title: ' + videoTitle + '\nDuration: ' + durationSeconds + ' seconds\nRequested Clips: ' + numberOfClips + '\n\nIdentify the ' + numberOfClips + ' most viral/trending moments. Each clip must be 20-60 seconds long. Return ONLY a JSON array like: [{"clipNumber":1,"startTime":0,"endTime":45,"viralReason":"Strong hook"}]';

const qwenClipBody = {
  model: 'qwen-plus',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  temperature: 0.7,
  max_tokens: 1000
};

return [{ json: { videoId, numberOfClips, aspectRatio, applyCaptions, executionId, workflowStartTime, videoUrl, videoTitle, durationSeconds, qwenClipBody } }];

const qwenResp = $input.first().json;
const streamData = $('Build Drive URL').first().json;
const { videoUrl, videoTitle, durationSeconds, numberOfClips, aspectRatio, applyCaptions, executionId, workflowStartTime } = streamData;
let clips = [];
try {
  const content = qwenResp.choices[0].message.content.trim();
  const jsonMatch = content.match(/\[([\s\S]*)\]/);
  if (jsonMatch) { clips = JSON.parse('[' + jsonMatch[1] + ']'); } else { clips = JSON.parse(content); }
} catch (e) {
  const cd = Math.min(45, Math.floor(durationSeconds / numberOfClips));
  for (let i = 0; i < numberOfClips; i++) { clips.push({ clipNumber: i + 1, startTime: i * cd, endTime: (i * cd) + cd, viralReason: 'Trending Moment ' + (i + 1) }); }
}
clips = clips.slice(0, numberOfClips);
while (clips.length < numberOfClips) {
  const last = clips[clips.length - 1] || { endTime: 0 };
  clips.push({ clipNumber: clips.length + 1, startTime: last.endTime || 0, endTime: Math.min((last.endTime || 0) + 45, durationSeconds), viralReason: 'Clip ' + (clips.length + 1) });
}
return clips.map(function(clip, idx) {
  const clipDuration = Math.max(5, (clip.endTime || clip.startTime + 30) - clip.startTime);
  const clipNumber = clip.clipNumber || (idx + 1);
  const videoTrack = { clips: [{ asset: { type: 'video', src: videoUrl, trim: clip.startTime, volume: 1 }, start: 0, length: clipDuration, fit: 'cover' }] };
  const tracks = [videoTrack];
  if (applyCaptions) {
    tracks.unshift({ clips: [{ asset: { type: 'html', html: '<p>' + (clip.viralReason || '') + '</p>', css: 'p{font-family:Arial Black,sans-serif;font-size:28px;color:#FFF;background:rgba(0,0,0,0.65);padding:10px 20px;border-radius:10px;text-align:center;}', width: 540, height: 120 }, start: 0, length: clipDuration, position: 'bottom', offset: { x: 0, y: -0.08 } }] });
  }
  return { json: { clipNumber: clipNumber, viralReason: clip.viralReason || ('Clip ' + clipNumber), clipStartTime: clip.startTime, clipEndTime: clip.endTime, clipDuration: clipDuration, videoTitle: videoTitle, executionId: executionId, workflowStartTime: workflowStartTime, aspectRatio: aspectRatio, shotstackPayload: { timeline: { tracks: tracks }, output: { format: 'mp4', aspectRatio: aspectRatio, resolution: 'hd', fps: 30 } } } };
});

const submitResults = $input.all();
const buildItems = $('Build Shotstack Items').all();
const renderIds = submitResults.map(function(item, idx) {
  const resp = item.json || {};
  const renderId = resp.response && resp.response.id ? resp.response.id : (resp.id || null);
  if (!renderId) throw new Error('Shotstack submission failed for clip ' + (idx + 1) + ': ' + JSON.stringify(resp).slice(0, 200));
  const bi = buildItems[idx] && buildItems[idx].json ? buildItems[idx].json : {};
  return { renderId: renderId, clipNumber: bi.clipNumber || (idx + 1), clipDuration: bi.clipDuration || null, viralReason: bi.viralReason || null };
});
const first = buildItems[0] && buildItems[0].json ? buildItems[0].json : {};
return [{ json: { renderIds: renderIds, executionId: first.executionId, workflowStartTime: first.workflowStartTime, videoTitle: first.videoTitle, numberOfClips: renderIds.length } }];

const driveResults = $input.all();
const extractedItems = $('Download Rendered Clips').all();
const first = extractedItems[0] && extractedItems[0].json ? extractedItems[0].json : {};
const clipsWithDrive = driveResults.map(function(item, idx) {
  const driveFile = item.json || {};
  const original = extractedItems[idx] && extractedItems[idx].json ? extractedItems[idx].json : {};
  return { clipNumber: original.clipNumber || (idx + 1), shotstackUrl: original.shotstackUrl, driveFileId: driveFile.id, driveUrl: driveFile.webViewLink, viralReason: original.viralReason, clipDuration: original.clipDuration };
});
const videoTitle = first.videoTitle || 'YouTube Video';
const qwenMetaBody = {
  model: 'qwen-plus',
  messages: [
    { role: 'system', content: 'You are a viral social media content creator. Generate catchy hook titles, short descriptions, and trending hashtags. Return ONLY a valid JSON array, no markdown.' },
    { role: 'user', content: 'Generate hook titles, descriptions and hashtags for ' + clipsWithDrive.length + ' video clips from: "' + videoTitle + '". Return ONLY this JSON array: [{"clipNumber":1,"hookTitle":"Catchy hook here!","description":"Short engaging description.","hashtags":"#viral #shorts #trending #youtube"}]' }
  ],
  temperature: 0.8,
  max_tokens: 2000
};
return [{ json: { clips: clipsWithDrive, executionId: first.executionId, workflowStartTime: first.workflowStartTime, videoTitle: videoTitle, numberOfClips: clipsWithDrive.length, qwenMetaBody: qwenMetaBody } }];

const qwenResp = $input.first().json;
const driveData = $('Collect Drive Data').first().json;
let clipsMetadata = [];
try {
  const content = qwenResp.choices[0].message.content.trim();
  const jsonMatch = content.match(/\[([\s\S]*)\]/);
  if (jsonMatch) { clipsMetadata = JSON.parse('[' + jsonMatch[1] + ']'); } else { clipsMetadata = JSON.parse(content); }
} catch (e) {
  clipsMetadata = driveData.clips.map(function(c) { return { clipNumber: c.clipNumber, hookTitle: driveData.videoTitle + ' - Part ' + c.clipNumber, description: 'Viral clip from ' + driveData.videoTitle + '. Watch till the end!', hashtags: '#viral #shorts #trending #youtube' }; });
}
const enrichedClips = driveData.clips.map(function(clip, idx) {
  const meta = clipsMetadata.find(function(m) { return m.clipNumber === clip.clipNumber; }) || clipsMetadata[idx] || {};
  return { clipNumber: clip.clipNumber, shotstackUrl: clip.shotstackUrl, driveFileId: clip.driveFileId, driveUrl: clip.driveUrl, hookTitle: meta.hookTitle || (driveData.videoTitle + ' - Short #' + clip.clipNumber), description: meta.description || ('Viral clip from ' + driveData.videoTitle), hashtags: meta.hashtags || '#viral #shorts #trending #youtube' };
});
return [{ json: { makePayload: { executionId: driveData.executionId, videoTitle: driveData.videoTitle, totalClips: enrichedClips.length, clips: enrichedClips }, enrichedClips: enrichedClips, executionId: driveData.executionId, workflowStartTime: driveData.workflowStartTime, videoTitle: driveData.videoTitle, numberOfClips: enrichedClips.length } }];

const makeResp = $input.first().json;
const buildData = $('Build Make Payload').first().json;
const clipsString = (makeResp.clips || '').toString();
const enrichedClips = buildData.enrichedClips || [];
const workflowStartTime = buildData.workflowStartTime || Date.now();
const linkLines = clipsString.split('
').filter(function(l) { return l.trim(); });
const linkMap = {};
linkLines.forEach(function(line) {
  const parts = line.split('|');
  if (parts.length >= 3) { const clipNum = parseInt(parts[0]); linkMap[clipNum] = { ytId: parts[1].trim(), igId: parts[2].trim() }; }
});
const timespentMs = Date.now() - workflowStartTime;
const timespentMinutes = (Math.round(timespentMs / 1000 / 60 * 10) / 10) + ' min';
return enrichedClips.map(function(clip) {
  const links = linkMap[clip.clipNumber] || {};
  const ytId = links.ytId || '';
  const igId = links.igId || '';
  return { json: { clipNumber: clip.clipNumber, videoTitle: buildData.videoTitle, hookTitle: clip.hookTitle, igReelLink: igId ? 'https://www.instagram.com/reel/' + igId + '/' : '', youtubeShortLink: ytId ? 'https://www.youtube.com/shorts/' + ytId : '', status: 'Completed', timespent: timespentMinutes } };
});

const parseData = $('Parse Stream URL').first().json;
const driveFileId = $('Upload Source to Drive').first().json.id;
const driveVideoUrl = 'https://drive.google.com/uc?export=download&confirm=t&id=' + driveFileId;
return [{ json: { videoId: parseData.videoId, numberOfClips: parseData.numberOfClips, aspectRatio: parseData.aspectRatio, applyCaptions: parseData.applyCaptions, executionId: parseData.executionId, workflowStartTime: parseData.workflowStartTime, videoUrl: driveVideoUrl, videoTitle: parseData.videoTitle, durationSeconds: parseData.durationSeconds, qwenClipBody: parseData.qwenClipBody, sourceDriveFileId: driveFileId } }];

const data = $input.first().json;
return data.renderIds.map(function(r) {
  return { json: {
    renderId: r.renderId,
    clipNumber: r.clipNumber,
    clipDuration: r.clipDuration,
    viralReason: r.viralReason,
    executionId: data.executionId,
    workflowStartTime: data.workflowStartTime,
    videoTitle: data.videoTitle,
    numberOfClips: data.numberOfClips,
    pollAttempt: 0,
    shotstackUrl: null,
    renderStatus: 'queued'
  }};
});

const pollResp = $input.first().json;
const prevData = $('Init Poll State').item ? $('Init Poll State').item.json : null;

// Walk back up the chain to get the original item data
let origData = {};
try { origData = $('Init Poll State').item.json; } catch(e) {}

const response = (pollResp && pollResp.response) ? pollResp.response : {};
const status = response.status || 'unknown';
const url = response.url || null;
const pollAttempt = (origData.pollAttempt || 0) + 1;
const MAX_ATTEMPTS = 20;

if (status === 'failed') {
  throw new Error('Shotstack render failed for clip ' + origData.clipNumber + ': ' + (response.error || 'Unknown error'));
}

if (status === 'done' && url) {
  return [{ json: {
    ...origData,
    pollAttempt,
    renderStatus: 'done',
    shotstackUrl: url
  }}];
}

if (pollAttempt >= MAX_ATTEMPTS) {
  throw new Error('Render timed out after ' + MAX_ATTEMPTS + ' attempts (~5 min) for clip ' + origData.clipNumber + '. Last status: ' + status);
}

// Still rendering — pass through with updated attempt count
return [{ json: {
  ...origData,
  pollAttempt,
  renderStatus: status
}}];
